parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "SEBChatbotResponse",
  "type": "object",
  "required": [
    "replymessages",
    "intent",
    "confidence",
    "botState",
    "slotValues"
  ],
  "properties": {
    "replymessages": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["type", "text"],
        "properties": {
          "type": {
            "type": "string",
            "enum": ["Text"]
          },
          "text": {
            "type": "string",
            "minLength": 1
          }
        },
        "additionalProperties": false
      }
    },
    "intent": {
      "type": "string",
      "enum": ["CarinaBot"]
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "botState": {
      "type": "string",
      "enum": ["MOREDATA", "COMPLETE"],
      "description": "MOREDATA = more clarification required; COMPLETE = user ends chat or confirms agent transfer"
    },
    "slotValues": {
      "type": "object",
      "required": ["chatInput", "nextSteps", "language"],
      "properties": {
        "chatInput": {
          "type": "string"
        },
        "nextSteps": {
          "type": "string",
          "enum": ["transferAgent", "transferSurvey", "mainMenu", "emergency", "null"],
          "description": "transferAgent = escalate to human agent; mainMenu = when request for main menu; null = continue conversation (default)"
        },
        "language": {
          "type": "string",
          "enum": ["english", "malay"],
          "description": "transferAgent = when language detected is english or unkown; malay = when language detected is malay"
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

parameters.jsCode:
// Get all input items
const items = $input.all();

// Loop through items
items.forEach(item => {
  const output = item.json.output;

  // Guard check
  if (output && Array.isArray(output.replymessages)) {
    output.replymessages.forEach(msg => {
      // Fix: Check for "Text" with capital T
      if (msg.type === "Text" && msg.text) {
        // Replace **bold** with *italic*
        msg.text = msg.text.replace(/\*\*(.*?)\*\*/g, '*$1*').trim();
      }
    });
  }
});

// Return modified items
return items;

// Error handler for N8N with defensive checks
const errorData = $input.first().json;

// Handle different error data structures
let workflow, error, nodeName, description, timestamp, executionId, executionUrl, mode;

// Helper: format timestamp to Malaysia time
function formatMYTime(dateInput) {
  return new Date(dateInput).toLocaleString('en-US', {
    dateStyle: 'long',
    timeStyle: 'medium',
    timeZone: 'Asia/Kuala_Lumpur'
  });
}

// Check if this is a trigger error format
if (errorData.trigger?.error && errorData.workflow) {
  workflow = errorData.workflow;
  error = errorData.trigger.error;
  mode = errorData.trigger.mode || 'unknown';
  nodeName = error.context?.nodeCause || error.node?.name || 'Trigger Node';
  description = error.context?.messageTemplate || error.context?.description || 'Trigger error occurred';
  timestamp = error.timestamp ? formatMYTime(error.timestamp) : formatMYTime(Date.now());
  executionId = workflow.id || 'N/A';
  executionUrl = workflow.url || `https://your-n8n-instance.com/workflow/${workflow.id}`;
}

// Check if this is a workflow execution error format
else if (errorData.workflow && errorData.execution) {
  workflow = errorData.workflow;
  const execution = errorData.execution;
  error = execution.error || {};
  mode = execution.mode || 'execution';
  nodeName = error.context?.nodeCause || error.node?.name || 'Unknown Node';
  description = error.context?.messageTemplate || error.description || 'No description available';
  timestamp = error.timestamp ? formatMYTime(error.timestamp) : formatMYTime(Date.now());
  executionId = execution.id || 'N/A';
  executionUrl = execution.url || '#';
}

// Handle direct error format
else if (errorData.errorMessage) {
  workflow = { name: 'Unknown Workflow', id: 'N/A' };
  error = {
    name: errorData.errorDescription || 'Error',
    message: errorData.errorMessage,
    timestamp: Date.now()
  };
  mode = 'direct';
  nodeName = errorData.n8nDetails?.nodeName || 'Unknown Node';
  description = errorData.n8nDetails?.nodeType || 'No description available';
  timestamp = formatMYTime(Date.now());
  executionId = 'N/A';
  executionUrl = '#';
}

// Fallback for unknown format
else {
  workflow = { name: 'Unknown Workflow', id: 'N/A' };
  error = {
    name: 'Unknown Error',
    message: JSON.stringify(errorData),
    timestamp: Date.now()
  };
  mode = 'unknown';
  nodeName = 'Unknown Node';
  description = 'Error data format not recognized';
  timestamp = formatMYTime(Date.now());
  executionId = 'N/A';
  executionUrl = '#';
}

// Create simple HTML table
const htmlMessage = `
<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>N8N Workflow Error</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            padding: 20px;
        }
        table {
            border-collapse: collapse;
            width: 100%;
            max-width: 800px;
        }
        th, td {
            border: 1px solid #ddd;
            padding: 12px;
            text-align: left;
        }
        th {
            background-color: #f2f2f2;
            font-weight: bold;
        }
        h2 {
            text-align: center;
        }
        .btn {
            display: inline-block;
            background: #007bff;
            color: white;
            padding: 8px 16px;
            text-decoration: none;
            border-radius: 4px;
        }
    </style>
</head>
<body>
    <h2>🚨 Workflow Error Alert</h2>

    <table>
        <tr><td><strong>Workflow Name</strong></td><td>${workflow.name}</td></tr>
        <tr><td><strong>Failed Node</strong></td><td>${nodeName}</td></tr>
        <tr><td><strong>Mode</strong></td><td>${mode}</td></tr>
        <tr><td><strong>Error Type</strong></td><td>${error.name}</td></tr>
        <tr><td><strong>Error Message</strong></td><td>${error.message}</td></tr>
        <tr><td><strong>Description</strong></td><td>${description}</td></tr>
        <tr><td><strong>Execution ID</strong></td><td>${executionId}</td></tr>
        <tr><td><strong>Timestamp (MYT)</strong></td><td>${timestamp}</td></tr>
        <tr><td><strong>View Execution</strong></td>
            <td><a href="${executionUrl}" class="btn" target="_blank">Open Dashboard</a></td>
        </tr>
    </table>
</body>
</html>
`.trim();

return {
  html: htmlMessage,
  workflow_name: workflow.name,
  error_level: error.level || 'error',
  execution_id: executionId,
  node_name: nodeName,
  error_message: error.message
};

